cd /var/tmp/loop-bench/runs/0d9a3d4e50ad/workspace/target; cat > /tmp/fix.mjs <<'EOF'
import fs from 'fs';
const t='src/orchestration/chatOrchestrator.test.ts';
const lines=fs.readFileSync(t,'utf8').split('\n');
for (const f of ['specs/hal-engine-architecture/spec.md','specs/hal-engine-tool-input-validation/spec.md','specs/hal-engine-config-hooks/spec.md']){
  let s=fs.readFileSync(f,'utf8');
  s=s.replace(/\[validated by: ([^\]]+)\]\((\.\.\/\.\.\/src\/orchestration\/chatOrchestrator\.test\.ts)#L\d+\)/g,(m,name,p)=>{
    const idx=lines.findIndex(l=>/^\s*it\(/.test(l)&&l.includes(`'${name}'`));
    if(idx<0){console.log('MISSING',name);return m;}
    return `[validated by: ${name}](${p}#L${idx+1})`;
  });
  fs.writeFileSync(f,s);
}
EOF
node /tmp/fix.mjs; git diff --stat; sed -i "s/timestamp: new Date().toISOString()/timestamp: '2026-01-01T00:00:00.000Z'/" src/orchestration/onErrorNonError.acceptance.test.ts; grep -n timestamp src/orchestration/onErrorNonError.acceptance.test.ts; grep -n "works without any hooks" specs -r
